    fun inputBits(index: Int): IntArray = rows[index].copyOfRange(0, INPUTS)
    fun androidBits(index: Int): Int = rows[index][INPUTS]
    fun inputFloats(index: Int): FloatArray =
        FloatArray(INPUTS) { Float.fromBits(inputBits(index)[it]) }
}

internal fun hexToBytes(hex: String): ByteArray {
    val out = ByteArray(hex.length / 2)
    var i = 0
    while (i < out.size) {
        out[i] = hex.substring(i * 2, i * 2 + 2).toInt(16).toByte()
        i++
    }
    return out
}
